//compare this number object to the argument specified.
public class CompareToExample {
    public static void main(String args[]) {
        // creating an integer class object with valuee "10"
        Integer i = new Integer("10");
        // comparing value of i
        System.out.println(i.compareTo(7));
        System.out.println(i.compareTo(17));
        System.out.println(i.compareTo(10));

    }
}
